    </div>

    <!-- =================================== -->
    <!-- ÍCONE FLUTUANTE DA SACOLA -->
    <!-- =================================== -->
    <div class="floating-cart-icon" id="cart-button">
        🛒 <span id="cart-count" style="position: absolute; top: -8px; right: -10px; background-color: red; border-radius: 50%; padding: 2px 6px; font-size: 10px;">0</span>
