        function atualizarCarrinho() {
            cartItemsList.innerHTML = ''; // Limpa a lista atual
            let total = 0;

            if (cart.length === 0) {
                cartItemsList.innerHTML = '<p style="text-align: center; color: #888;">Sua sacola está vazia.</p>';
            } else {
                cart.forEach((item, index) => {
                    const itemTotal = item.preco;
                    total += itemTotal;

                    // Cria o elemento HTML para cada item
                    const itemDiv = document.createElement('div');
                    itemDiv.style.padding = '10px 0';
                    itemDiv.style.borderBottom = '1px dotted #eee';
