                    cartItemsList.appendChild(itemDiv);
                });

                // Adiciona funcionalidade de remover item (delegation)
                cartItemsList.querySelectorAll('button').forEach(removeBtn => {
                    removeBtn.addEventListener('click', function() {
                        const index = parseInt(this.dataset.index);
                        cart.splice(index, 1); // Remove o item do array
                        atualizarCarrinho(); // Re-renderiza
                    });
                });
            }

            // Atualiza o total e o contador
            cartTotalElement.textContent = `R$ ${total.toFixed(2)}`;
            cartCountElement.textContent = cart.length;
        }


